import { BackgroundOrchestrator } from "./BackgroundOrchestrator";
import { CornerOrnament } from "./covers/CornerOrnament";
import { pageStyleClass, resolvePageStyle } from "./utils/pageStyle";
import { buildWordCloud } from "./utils/wordCloud";
import type { AlbumConfig } from "./types";

export interface WordCloudPageProps {
  album: AlbumConfig;
}

/** Smallest and largest type in the cloud, as a multiple of the page's size. */
const MIN_SCALE = 0.92;
const MAX_SCALE = 2.6;

/**
 * A page built from the words the album's greetings used most.
 *
 * The words are laid out as centred wrapping text rather than packed into a
 * shape: packing needs measurement, and this page has to render identically on
 * the server, in the browser and on paper. Weight is carried by size, ink
 * strength and a slight baseline shift, which reads as a cloud while staying
 * pure CSS — so it reflows on a phone and prints without a canvas.
 */
export function WordCloudPage({ album }: WordCloudPageProps) {
  const words = buildWordCloud(album);

  return (
    <BackgroundOrchestrator
      global={album.globalBackground}
      ornament={
        <div className="ae-page__ornament" aria-hidden="true">
          <CornerOrnament style={resolvePageStyle(album)} surface="page" />
        </div>
      }
      className={`ae-page ae-page--cloud ${pageStyleClass(album, false)}`}
    >
      <div className="ae-cloud">
        <h2
          className="ae-cloud__title"
          style={{ fontFamily: album.defaultFontFamily || "Rubik" }}
        >
          {album.wordCloudTitle || "המילים שלכם"}
        </h2>

        {words.length === 0 ? (
          <p className="ae-cloud__empty">אין עדיין מספיק מילים לענן.</p>
        ) : (
          <ul className="ae-cloud__words">
            {words.map((word) => (
              <li
                key={word.text}
                className="ae-cloud__word"
                style={{
                  fontFamily: album.defaultFontFamily || "Rubik",
                  fontSize: `${scale(word.weight).toFixed(2)}em`,
                  // The rarest words recede rather than disappear; the page
                  // style supplies the ink so a dark page still reads.
                  opacity: 0.68 + word.weight * 0.32,
                  fontWeight: word.weight > 0.55 ? 700 : 400,
                }}
                title={`${word.text} · ${word.count}`}
              >
                {word.text}
              </li>
            ))}
          </ul>
        )}
      </div>
    </BackgroundOrchestrator>
  );
}

function scale(weight: number): number {
  return MIN_SCALE + weight * (MAX_SCALE - MIN_SCALE);
}
